function matchesChat(c,q){return !q||c.title.toLowerCase().includes(q)||c.messages.some(m=>m.content.toLowerCase().includes(q));}
function sortedChats(){return [...data.chats].sort((a,b)=>Number(!!b.pinned)-Number(!!a.pinned)||b.updatedAt-a.updatedAt);}
function selectChat(id){if(busy){toast('Stop the current reply before switching conversations.');return;}disconnectAgent();activeId=id;$('#chat-error').hidden=true;setView('chat');}
function renderHistory(){const q=$('#search-chats').value.trim().toLowerCase(),list=$('#history');list.replaceChildren();const chats=sortedChats().filter(c=>matchesChat(c,q));for(const c of chats){const b=el('button','history-item'+(c.id===activeId?' active':''));b.append(el('span','history-mark',c.pinned?'✦':'◌'),el('span','history-title',c.title));b.title=c.title;b.setAttribute('aria-label',(c.pinned?'Pinned: ':'')+c.title);list.append(bind(b,()=>selectChat(c.id)));}if(!chats.length)list.append(el('p','history-empty',q?'No conversations found.':'Your next conversation starts here.'));}
event('#search-chats','input',renderHistory);
event('#pin-chat','click',async()=>{const c=current();if(!c||busy)return;c.pinned=!c.pinned;await persist();render();toast(c.pinned?'Conversation pinned':'Conversation unpinned');});
event('#rename-chat','click',()=>{const c=current();if(!c||busy)return;openEditor('Rename conversation',[field('Conversation title','title',{value:c.title,required:true,maxLength:120})],async f=>{const title=f.get('title').trim();if(!title)throw new Error('Enter a title.');c.title=title;await persist();render();toast('Conversation renamed');});});
async function branchAt(message,edit){if(busy){toast('Stop the current reply before branching.');return;}const c=current();if(!c)return;const index=c.messages.findIndex(m=>m.id===message.id),count=edit?index:index+1;const branch={...structuredClone(c),id:uid(),title:'Branch · '+c.title.replace(/^Branch · /,''),pinned:false,messages:structuredClone(c.messages.slice(0,count)),updatedAt:Date.now()};data.chats.push(branch);activeId=branch.id;await persist();setView('chat');$('#prompt').value=edit?message.content:'';$('#prompt').focus();toast(edit?'Original kept. Edit the draft, then send.':'Branch created. Original conversation kept.');}
// A deliberately small Markdown renderer; no raw HTML, remote images, or dynamic code.
function inlineFormat(text){const f=document.createDocumentFragment();const pattern=/(`[^`\n]+`|\*\*[^*\n]+\*\*)/g;let match,last=0;while((match=pattern.exec(text))){f.append(document.createTextNode(text.slice(last,match.index)));const code=match[0][0]==='`',node=el(code?'code':'strong','',match[0].slice(code?1:2,code?-1:-2));f.append(node);last=pattern.lastIndex;}f.append(document.createTextNode(text.slice(last)));return f;}
function formatMessage(text){const fragment=document.createDocumentFragment(),parts=text.split(/(```[^\n]*\n[\s\S]*?(?:```|$))/g);for(const part of parts){if(!part)continue;if(part.startsWith('```')){const first=part.indexOf('\n'),language=part.slice(3,first).trim().slice(0,40),code=part.slice(first+1).replace(/```$/,'').replace(/\n$/,'');const box=el('div','code-block'),head=el('div','code-head');head.append(el('span','',language||'code'),bind(el('button','','Copy code'),async()=>{await navigator.clipboard.writeText(code);toast('Code copied');}));const pre=el('pre'),content=el('code','',code);pre.append(content);box.append(head,pre);fragment.append(box);continue;}let list=null;for(const line of part.split('\n')){const heading=line.match(/^(#{1,3})\s+(.+)/),bullet=line.match(/^\s*(?:[-*]|\d+\.)\s+(.+)/);if(bullet){if(!list){list=el('ul');fragment.append(list);}const item=el('li');item.append(inlineFormat(bullet[1]));list.append(item);continue;}list=null;if(!line.trim()){fragment.append(el('div','message-gap'));continue;}const node=el(heading?'h'+(heading[1].length+1):'p');node.append(inlineFormat(heading?heading[2]:line));fragment.append(node);}}return fragment;}
function quickOpen(){if(!data)return;$('#quick-query').value='';quickResults();$('#quick-dialog').showModal();$('#quick-query').focus();}
function quickResults(){if(!data)return;const q=$('#quick-query').value.trim().toLowerCase(),list=$('#quick-results');list.replaceChildren();const actions=[['New conversation',()=>$('#new-chat').click()],['Memories',()=>setView('memories')],['Skills',()=>setView('skills')],['Settings & models',()=>setView('settings')],['Lock workspace',lock]];for(const [label,action] of actions.filter(([label])=>!q||label.toLowerCase().includes(q))){const b=el('button','quick-item');b.append(el('span','','↗'),el('span','',label),el('small','','ACTION'));list.append(bind(b,()=>{$('#quick-dialog').close();return action();}));}for(const c of sortedChats().filter(c=>matchesChat(c,q)).slice(0,30)){const b=el('button','quick-item');b.append(el('span','',c.pinned?'✦':'◌'),el('span','',c.title),el('small','','CHAT'));list.append(bind(b,()=>{$('#quick-dialog').close();selectChat(c.id);}));}if(!list.children.length)list.append(el('p','history-empty','No matches. Try another word.'));}
